import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Download, FileText, GitCompare, AlertTriangle } from 'lucide-react'
import { cn } from '@/utils/cn'
import { apiHelpers } from '@/services/api'

export const Reports = () => {
  const [vid, setVid] = useState('')
  const [type, setType] = useState('executive')
  const [format, setFormat] = useState('json')
  const [fromId, setFromId] = useState('')
  const [toId, setToId] = useState('')

  const { data: list } = useQuery({ queryKey:['validations-list'], queryFn:()=>apiHelpers.get<any>('/validations') })
  const { data: report, refetch: fetchReport } = useQuery({
    queryKey:['report', vid, type, format],
    queryFn:()=>apiHelpers.get<any>(`/validations/${vid}/reports?type=${type}&format=${format}`),
    enabled: false,
  })
  const { data: diff, refetch: fetchDiff } = useQuery({
    queryKey:['diff', fromId, toId],
    queryFn:()=>apiHelpers.get<any>(`/reports/compare?from_id=${fromId}&to_id=${toId}`),
    enabled: false,
  })

  const download = (content:string, name:string) => {
    const blob = new Blob([content], {type:'text/plain'})
    const url = URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); URL.revokeObjectURL(url)
  }

  return (
    <div className="p-6 max-w-6xl mx-auto space-y-4">
      <div>
        <h1 className="text-2xl font-bold">Reports</h1>
        <p className="text-sm text-muted-foreground">Executive • Technical • Evidence • Compliance • Risk + PDF/HTML/Markdown/JSON/CSV + Previous vs Current diff (Remediation Verification)</p>
      </div>

      <div className="rounded-xl border bg-card p-4 space-y-3">
        <div className="flex flex-wrap gap-2 items-end">
          <div><label className="text-xs">Validation ID</label><input value={vid} onChange={e=>setVid(e.target.value)} placeholder="val-xxxx" className="block mt-1 px-2 py-1.5 rounded border bg-background text-xs font-mono w-40" /></div>
          <div><label className="text-xs">Type</label><select value={type} onChange={e=>setType(e.target.value)} className="block mt-1 px-2 py-1.5 rounded border bg-background text-xs"><option value="executive">Executive</option><option value="technical">Technical</option><option value="evidence">Evidence</option><option value="compliance">Compliance</option><option value="risk">Risk</option></select></div>
          <div><label className="text-xs">Format</label><select value={format} onChange={e=>setFormat(e.target.value)} className="block mt-1 px-2 py-1.5 rounded border bg-background text-xs"><option value="json">JSON</option><option value="html">HTML</option><option value="markdown">Markdown</option><option value="csv">CSV</option></select></div>
          <button onClick={()=>fetchReport()} disabled={!vid} className="px-3 py-1.5 rounded bg-primary text-primary-foreground text-xs disabled:opacity-50">Generate</button>
          {report && <button onClick={()=>{
            const c = report.csv || report.markdown || report.html || JSON.stringify(report, null, 2)
            download(c, `${vid}-${type}.${format==='json'?'json':format==='markdown'?'md':format}`)
          }} className="px-3 py-1.5 rounded border bg-card text-xs inline-flex items-center gap-1"><Download className="h-3 w-3" /> Download</button>}
        </div>
        {report && (
          <div className="rounded border bg-muted/20 p-3 max-h-64 overflow-auto text-xs">
            {report.simulation && <div className="flex gap-1 items-center text-amber-600 text-[11px] mb-2"><AlertTriangle className="h-3 w-3" /> Simulation/Demo Data</div>}
            <pre className="whitespace-pre-wrap text-[11px]">{report.markdown || report.html || report.csv || JSON.stringify(report.content, null, 2)}</pre>
          </div>
        )}
        <div className="text-xs text-muted-foreground">Recent validations: {(list||[]).slice(0,5).map((v:any)=> <button key={v.id} onClick={()=>setVid(v.id)} className="mr-2 underline font-mono">{v.id}</button>)}</div>
      </div>

      <div className="rounded-xl border bg-card p-4 space-y-3">
        <h3 className="text-sm font-semibold flex items-center gap-2"><GitCompare className="h-4 w-4" /> Remediation Verification — Previous vs Current</h3>
        <div className="flex gap-2 items-end">
          <div><label className="text-xs">From (Previous)</label><input value={fromId} onChange={e=>setFromId(e.target.value)} placeholder="val-xxxx" className="block mt-1 px-2 py-1.5 rounded border bg-background text-xs font-mono w-40" /></div>
          <div><label className="text-xs">To (Current)</label><input value={toId} onChange={e=>setToId(e.target.value)} placeholder="val-xxxx" className="block mt-1 px-2 py-1.5 rounded border bg-background text-xs font-mono w-40" /></div>
          <button onClick={()=>fetchDiff()} disabled={!fromId||!toId} className="px-3 py-1.5 rounded bg-primary text-primary-foreground text-xs disabled:opacity-50">Compare</button>
        </div>
        {diff && (
          <div className="rounded border p-3 bg-muted/20 text-xs">
            <div className="grid grid-cols-3 gap-3 text-center">
              <div><div className="text-muted-foreground">From Score</div><div className="text-lg font-bold">{diff.from.risk_score}</div></div>
              <div><div className="text-muted-foreground">To Score</div><div className="text-lg font-bold">{diff.to.risk_score}</div></div>
              <div><div className="text-muted-foreground">Delta</div><div className={cn('text-lg font-bold', diff.risk_delta>0 ? 'text-emerald-600' : diff.risk_delta<0 ? 'text-destructive' : '')}>{diff.risk_delta>0?`+${diff.risk_delta}`:diff.risk_delta} {diff.risk_delta>0?'↑':'↓'}</div></div>
            </div>
            <div className="mt-3 flex gap-2 flex-wrap">
              {Object.entries(diff.diff).map(([k,v]:any)=> <span key={k} className={cn('px-2 py-0.5 rounded text-[11px] capitalize', (v as number)<0 ? 'bg-emerald-500 text-white' : (v as number)>0 ? 'bg-destructive text-destructive-foreground' : 'bg-muted')}>{k}: {v>0?`+${v}`:v}</span>)}
            </div>
            <div className="mt-2 text-[11px] text-muted-foreground">{diff.remediation_verification}</div>
            <div className="mt-2 font-mono text-[11px]">Critical: {diff.from.severity.critical} → {diff.to.severity.critical} &nbsp; High: {diff.from.severity.high} → {diff.to.severity.high} &nbsp; Medium: {diff.from.severity.medium} → {diff.to.severity.medium}</div>
          </div>
        )}
      </div>
    </div>
  )
}
